module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);
    reg [3:0] stack_mem [0:3];
    reg [1:0] SP;

    integer i;
    assign EMPTY = (SP == 2'b11) ? 1'b1 : 1'b0;
    assign FULL = (SP == 2'b00) ? 1'b1 : 1'b0;
    assign dataOut = stack_mem[SP];
    always @(posedge Clk or posedge Rst) begin
        if(Rst) begin
            SP <= 2'b11;
            for(i = 0;i < 4;i=i+1) 
                stack_mem[i] <= 4'b0;
        end
        else if(EN) begin
            if(!RW && !FULL) begin
                stack_mem[SP-1] <= dataIn;
                SP <= SP - 1;
            end
            else if(RW && !EMPTY) begin
                SP <= SP + 1;
                stack_mem[SP] <= 4'b0;
            end
        end
    end

endmodule
